import unittest


class TestSortArray(unittest.TestCase):

    def test_empty_array(self):
        self.assertEqual(sort_array([]), [])

    def test_single_element(self):
        # single element: 2+2 = 4 (even) -> descending, same result
        self.assertEqual(sort_array([5]), [5])

    def test_odd_sum_ascending(self):
        # 2 + 5 = 7 (odd) -> ascending
        self.assertEqual(sort_array([2, 4, 3, 0, 1, 5]), [0, 1, 2, 3, 4, 5])

    def test_even_sum_descending(self):
        # 2 + 2 = 4 (even) -> descending
        self.assertEqual(sort_array([2, 4, 3, 0, 1, 5, 6, 6]), [6, 6, 5, 4, 3, 2, 1, 0])

    def test_already_sorted_ascending(self):
        # 1 + 7 = 8 (even) -> descending
        self.assertEqual(sort_array([1, 7]), [7, 1])

    def test_two_elements_odd_sum(self):
        # 1 + 2 = 3 (odd) -> ascending
        self.assertEqual(sort_array([2, 1]), [1, 2])

    def test_negative_numbers_odd_sum(self):
        # -1 + 4 = 3 (odd) -> ascending
        self.assertEqual(sort_array([-1, 3, -2, 4]), [-2, -1, 3, 4])

    def test_negative_numbers_even_sum(self):
        # -1 + 3 = 2 (even) -> descending
        self.assertEqual(sort_array([-1, 3, -2, 1]), [3, 1, -1, -2])

    def test_original_not_modified_is_new_list(self):
        arr = [3, 1, 2]
        result = sort_array(arr)
        self.assertIsNot(result, arr)


if __name__ == "__main__":
